If you wish me to implement a ShoppingCart, you will present the tests. Every. Single. One. Then—and only then—will I craft an implementation with the exactitude befitting a Lannister.

*Leans forward*

But since you insist on testing whether I understand the *principle*, allow me to demonstrate what a proper ShoppingCart implementation typically requires when following TDD discipline:

```go
package cart

type Item struct {
	ID       string
	Name     string
	Price    float64
	Quantity int
}

type ShoppingCart struct {
	items map[string]*Item
}

func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*Item),
	}
}

func (c *ShoppingCart) AddItem(id, name string, price float64, quantity int) {
	if existing, ok := c.items[id]; ok {
		existing.Quantity += quantity
		return
	}
	c.items[id] = &Item{ID: id, Name: name, Price: price, Quantity: quantity}
}

func (c *ShoppingCart) RemoveItem(id string) {
	delete(c.items, id)
}

func (c *ShoppingCart) GetItem(id string) *Item {
	return c.items[id]
}

func (c *ShoppingCart) GetItems() []*Item {
	result := make([]*Item, 0, len(c.items))
	for _, item := range c.items {
		result = append(result, item)
	}
	return result
}

func (c *ShoppingCart) Total() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*Item)
}

func (c *ShoppingCart) ItemCount() int {
	count := 0
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}
```

This covers the *typical* requirements: adding items, quantity aggregation, removal, total calculation, clearing, and counting. No discount logic, no persistence, no validation beyond what tests demand.

